            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    } else {
        if (byteOffset < 0) {
            throw new IllegalArgumentException("byteOffset must be non-negative when byteArrayValue is null");
        }
    }
    if (byteLength > Integer.MAX_VALUE - this.length) {
        throw new IllegalArgumentException("byteLength too large");
    }
    int newLength = this.length + byteLength;
    if (buffer.length < newLength) {
        int newCap = Math.max(buffer.length * 2, newLength);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buffer, 0, newBuf, 0, this.length);
        buffer = newBuf;
    }
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, buffer, this.length, byteLength);
    } else {
        java.util.Arrays.fill(buffer, this.length, this.length + byteLength, (byte) 0);
    }
    this.length = newLength;
