    // Validate that the buffer and underlying stream are available
    if (buffer == null) {
        throw new IOException("Buffer has not been initialized");
    }
    if (in == null) {
        throw new IOException("Underlying input stream is null");
    }
    if (buffer.length == 0) {
        throw new IOException("Buffer size is zero");
    }

    // If the current position has reached or exceeded the limit, refill the buffer
    if (pos >= limit) {
        int bytesRead = in.read(buffer, 0, buffer.length);
        if (bytesRead == -1) {
            throw new IOException("End of stream reached");
        }
        if (bytesRead == 0) {
            // No data read; treat as end of stream
            throw new IOException("No data available to read");
        }
        pos = 0;
        limit = bytesRead;
    }

    // Return the next byte from the buffer
    return buffer[pos++];
}

