        throw new NullPointerException("Array is null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index greater than to index");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

