private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start and stop nodes must not be null");
    }
    // Create a circulator starting at the given node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node is already the stop node, return immediately
    if (start.equals(stop)) {
        return circ;
    }
    // Traverse the outer face until we hit the stop node or find a node that satisfies the predicate
    // We guard against infinite loops by stopping if we return to the start node
    while (true) {
        Node current = circ.getNode();
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
        // Move one step in the specified direction
        circ.move(dir);
        // If we have looped back to the start node without finding the stop node, break to avoid infinite loop
        if (circ.getNode().equals(start)) {
            // Stop node not found; return the circulator at the last visited node (which is the stop node if reachable)
            return circ;
        }
    }
}

