private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    for (int i = 0; i < n; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = vertexList.get(j);
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

