        if (i + 1 >= len) {
            throw new IllegalArgumentException("Trailing backslash in input");
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i++;
