private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i < 0 || i >= bb.limit()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + i);
    }
    int b1 = bb.get(i) & 0xFF;
    // ASCII
    if ((b1 & 0x80) == 0) {
        sb.append((char) b1);
        return i + 1;
    }
    int numBytes;
    if ((b1 & 0xE0) == 0xC0) {
        numBytes = 2;
    } else if ((b1 & 0xF0) == 0xE0) {
        numBytes = 3;
    } else if ((b1 & 0xF8) == 0xF0) {
        numBytes = 4;
    } else {
        // Invalid start byte
        sb.append('\uFFFD');
        return i + 1;
    }
    if (i + numBytes > bb.limit()) {
        sb.append('\uFFFD');
        return i + 1;
    }
    int[] bytes = new int[numBytes];
    bytes[0] = b1;
    for (int j = 1; j < numBytes; j++) {
        int b = bb.get(i + j) & 0xFF;
        if ((b & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        bytes[j] = b;
    }
    int codePoint;
    try {
        if (numBytes == 2) {
            codePoint = ((bytes[0] & 0x1F) << 6) | (bytes[1] & 0x3F);
        } else if (numBytes == 3) {
            codePoint = ((bytes[0] & 0x0F) << 12) | ((bytes[1] & 0x3F) << 6) | (bytes[2] & 0x3F);
        } else { // 4 bytes
            codePoint = ((bytes[0] & 0x07) << 18) | ((bytes[1] & 0x3F) << 12) | ((bytes[2] & 0x3F) << 6) | (bytes[3] & 0x3F);
        }
        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            codePoint -= 0x10000;
            char high = (char) (0xD800 + (codePoint >> 10));
            char low = (char) (0xDC00 + (codePoint & 0x3FF));
            sb.append(high).append(low);
        }
    } catch (Exception e) {
        sb.append('\uFFFD');
    }
    return i + numBytes;
}

