public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return segments;
    }
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
                // Use URI constructor to percent-decode without treating '+' as space
                value = new URI(null, null, part, null).getPath();
            } catch (URISyntaxException e) {
                throw new IllegalArgumentException("Invalid URI segment: " + part, e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

