public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    if (relativePath.isEmpty()) {
        return path;
    }

    boolean root = path.startsWith("/");
    // Normalize path components
    java.util.List<String> components = new java.util.ArrayList<>();
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            } else if (!root) {
                components.add("..");
            }
            // If root and components empty, ignore leading ".."
        } else {
            components.add(part);
        }
    }

    // Apply relative path components
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            } else if (!root) {
                components.add("..");
            }
            // If root and components empty, ignore leading ".."
        } else {
            components.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (root) {
        result.append("/");
    }
    for (int i = 0; i < components.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(components.get(i));
    }

    if (result.length() == 0) {
        return root ? "/" : ".";
    }
    return result.toString();
}

