protected void subAppend(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        StringBuilder sb = new StringBuilder();

        // Timestamp
        sb.append('[')
          .append(new java.util.Date(event.getTimeStamp()))
          .append("] ");

        // Log level
        sb.append('[')
          .append(event.getLevel())
          .append("] ");

        // Logger name
        sb.append('[')
          .append(event.getLoggerName())
          .append("] - ");

        // Message
        sb.append(String.valueOf(event.getMessage()));

        // Throwable information, if any
        if (event.getThrowableInformation() != null) {
            Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator())
                  .append(t.toString());
                for (StackTraceElement ste : t.getStackTrace()) {
                    sb.append(System.lineSeparator())
                      .append("\tat ")
                      .append(ste.toString());
                }
            }
        }

        // Write to standard output (or replace with actual writer if available)
        System.out.println(sb.toString());
    } catch (Exception e) {
        // Log the failure to standard error
        System.err.println("Failed to write log event: " + e.getMessage());
    }
}

