        throw new IllegalArgumentException("Appender name cannot be null or empty");
    }
    if (appenders == null) {
        return; // nothing to remove
    }
    synchronized (this) {
        Iterator<Appender> it = appenders.iterator();
        while (it.hasNext()) {
            Appender app = it.next();
            try {
                if (name.equals(app.getName())) {
                    it.remove();
                    // If the appender has a stop/close method, invoke it
                    try {
                        app.stop();
                    } catch (Exception e) {
                        // ignore failures during stop
                    }
                    break;
                }
            } catch (Exception e) {
                // If getName() throws, skip this appender
                continue;
            }
        }
    }
}

