public boolean isExpired(long timestamp, long expiredThreshold) {
    // If threshold is non-positive, consider it expired immediately
    if (expiredThreshold <= 0) {
        return true;
    }
    // If timestamp is not a valid time, consider it expired
    if (timestamp <= 0) {
        return true;
    }
    long now = System.currentTimeMillis();
    // If current time is before the timestamp, it cannot be expired
    if (now < timestamp) {
        return false;
    }
    // Determine if the elapsed time exceeds the threshold
    return now - timestamp > expiredThreshold;
