public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("file does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges must not be null");
    }
    List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (timeRanges.isEmpty()) {
        return result;
    }
    try (java.io.ObjectInputStream ois = new java.io.ObjectInputStream(new java.io.FileInputStream(file))) {
        while (true) {
            Object obj;
            try {
                obj = ois.readObject();
            } catch (java.io.EOFException eof) {
                break;
            }
            if (obj == null) {
                continue;
            }
            if (!(obj instanceof ThreadSnapshot)) {
                continue;
            }
            ThreadSnapshot ts = (ThreadSnapshot) obj;
            long tsTime;
            try {
                tsTime = ts.getTimestamp();
            } catch (Exception e) {
                // If getTimestamp is not available or throws, skip this snapshot
                continue;
            }
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                long start = range.getStartTime();
                long end = range.getEndTime();
                if (tsTime >= start && tsTime <= end) {
                    result.add(ts);
                    break;
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize ThreadSnapshot objects", e);
    }
    return result;
}

