public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int n = desiredCapacity;
    if (n % 2 == 0) {
        n++; // make it odd
    }
    while (true) {
        if (n <= 3) {
            return n; // 3 is prime
        }
        // Quick elimination of obvious composites
        if (n % 2 == 0 || n % 3 == 0) {
            // not prime, skip to next odd
        } else {
            boolean isPrime = true;
            for (int i = 5; (long) i * i <= n; i += 6) {
                if (n % i == 0 || n % (i + 2) == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                return n;
            }
        }
        n += 2; // skip even numbers
        // Prevent infinite loop in case of integer overflow
        if (n < 0) {
            throw new IllegalArgumentException("Desired capacity too large to find a prime");
        }
    }
}

