public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0) {
        throw new IndexOutOfBoundsException("index and len must be non-negative");
    }
    final int end = index + len;
    if (end > str.length() || end < index) { // check overflow
        throw new IndexOutOfBoundsException("index + len out of bounds");
    }

    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair -> 4 bytes
                size += 4;
                i++; // skip low surrogate
            } else {
                // Unmatched high surrogate -> treat as 3 bytes (replacement)
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unmatched low surrogate -> treat as 3 bytes (replacement)
            size += 3;
        } else {
            // BMP character that is not a surrogate
            size += 3;
        }
    }
    return size;
}

