private void checkIfPackedField() throws IOException {
    // Validate the current tag before processing.
    if (currentTag == 0) {
        throw new IOException("Invalid tag: tag value is zero");
    }
    // Extract the wire type from the tag (lower 3 bits).
    int wireType = currentTag & 0x7;
    // In protobuf, packed repeated fields are encoded as length-delimited.
    // If the wire type indicates length-delimited, mark the field as packed.
    if (wireType == 2) { // 2 == WIRETYPE_LENGTH_DELIMITED
        packed = true;
    } else {
        packed = false;
    }
}

